"use client";
import {FormEvent,useState} from "react";import {api} from "@/lib/api";
export default function Company(){const[org,setOrg]=useState<string>();const[msg,setMsg]=useState("");async function create(e:FormEvent<HTMLFormElement>){e.preventDefault();const f=new FormData(e.currentTarget);const r=await api<{id:string}>("/api/organizations",{method:"POST",body:JSON.stringify({name:f.get("name")})});setOrg(r.id);setMsg("تم إنشاء مساحة الشركة")};async function knowledge(e:FormEvent<HTMLFormElement>){e.preventDefault();const f=new FormData(e.currentTarget);await api(`/api/organizations/${org}/knowledge`,{method:"POST",body:JSON.stringify({name:f.get("name"),content:f.get("content"),attested_synthetic:f.get("attested")==="on"})});setMsg("تمت فهرسة المصدر وربطه بقاعدة معرفة الشركة")};return <main className="shell"><header className="topbar"><div className="brand"><span className="brandmark">V</span> Venv للشركات</div><nav className="nav"><a className="active">إعداد الشركة</a><a>الحملات</a><a>المرشحون</a><a>التقارير</a></nav></header><div className="content" style={{maxWidth:1000}}><span className="eyebrow">مسار تقييم المرشحين</span><h1 className="title">حوّل معاييركم إلى تجربة عمل قابلة للقياس</h1><p className="subtitle">ارفع معرفة منزوعة الهوية، راجع المهام قبل نشرها، ثم راقب تقارير الوكلاء دون التأثير على المهمة أثناء تنفيذها.</p><div className="grid" style={{gridTemplateColumns:"1fr 1fr"}}><form className="panel side form" onSubmit={create}><h2>1. مساحة الشركة</h2><label>اسم الشركة</label><input name="name" required/><button className="btn">إنشاء المساحة</button></form><form className="panel side form" onSubmit={knowledge}><h2>2. قاعدة المعرفة</h2><label>اسم المصدر</label><input name="name" required disabled={!org}/><label>المحتوى التجريبي</label><textarea name="content" rows={7} required disabled={!org}/><label><input name="attested" type="checkbox" style={{width:"auto",marginLeft:8}} required/> أؤكد أن البيانات وهمية أو منزوعة الهوية</label><button className="btn" disabled={!org}>فهرسة المصدر</button></form></div>{msg&&<div className="panel side" style={{marginTop:20}}>{msg}</div>}</div></main>}
